292	    /**
293	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
294	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
295	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
296	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
297	     */
298	    @Transient
299	    public Integer getMembershipPoints() {
300	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
301	            this.registrationDate);
302	    }
303	
304	    /**
305	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
306	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
307	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
308	     */
309	    @Transient
310	    public Integer getMembershipLevel() {
311	        return capMembershipLevel(membershipLevel(getMembershipPoints()), this.membershipLevelCap);
312	    }
313	
314	    /** The membership points derived from the given factors: they start at 0, add 2 when
315	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
316	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
317	     *  {@link #hasTenureBonus(LocalDate)}). */
318	    private static int membershipPoints(String email, Integer namesakeCount,
319	            Integer householdMemberCount, LocalDate registrationDate) {
320	        int points = 0;
321	        if (email != null && !email.isBlank()) {
322	            points += 2;
323	        }
324	        if (namesakeCount != null && namesakeCount == 0) {
325	            points += 1;
326	        }
327	        if (householdMemberCount != null && householdMemberCount >= 3) {
328	            points += 2;
329	        }
330	        if (hasTenureBonus(registrationDate)) {
331	            points += 3;
332	        }
333	        return points;
334	    }
335	
336	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
337	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
338	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
339	     *  bonus. */
340	    private static boolean hasTenureBonus(LocalDate registrationDate) {
341	        return registrationDate != null
342	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
343	    }
344	
345	    /**
346	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
347	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
348	     * following calendar year, and a date in January-June to the fiscal year ending that same year
349	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
350	     */
351	    public static int fiscalYear(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
354	
355	    /**
356	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
357	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the last two digits of the fiscal
358	     * year (starting 1 July) that contains the registration date (e.g. a date of 2026-09-05 yields
359	     * {@code "FY27"}). Returns {@code null} when no registration date is available.
360	     */
361	    @Transient
362	    public String getFiscalYear() {
363	        if (this.registrationDate == null) {
364	            return null;
365	        }
366	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
367	    }
368	
369	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
370	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
371	    private static int membershipLevel(int points) {
372	        if (points >= 6) {
373	            return 4;
374	        }
375	        if (points >= 4) {
376	            return 3;
377	        }
378	        if (points >= 2) {
379	            return 2;
380	        }
381	        return 1;
382	    }
383	
384	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
385	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
386	    private static int capMembershipLevel(int level, Integer cap) {
387	        return cap == null ? level : Math.min(level, cap);
388	    }
