429	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
430	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
438	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
439	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
440	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
441	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
442	     */
443	    @Transient
444	    public String getRegion() {
445	        String byPostcode = regionForPostcode(this.postcode);
446	        if (byPostcode != null) {
447	            return byPostcode;
448	        }
449	        if ("Sydney".equals(this.city)) {
450	            return "NSW";
451	        }
452	        if ("Melbourne".equals(this.city)) {
453	            return "VIC";
454	        }
455	        if ("Brisbane".equals(this.city)) {
456	            return "QLD";
457	        }
458	        return "UNKNOWN";
459	    }
