142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = currentIdempotencyKey();
146	        if (idempotencyKey != null) {
147	            Integer existingId = idempotentCreates.get(idempotencyKey);
148	            if (existingId != null) {
149	                Owner existing = this.clinicService.findOwnerById(existingId);
150	                if (existing != null) {
151	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
152	                }
153	            }
154	        }
155	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
156	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
157	                && response.getBody() != null && response.getBody().getId() != null) {
158	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
159	        }
160	        return response;
161	    }
