163	    /**
164	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
165	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
166	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
167	     */
168	    private static String currentIdempotencyKey() {
169	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
170	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
171	            if (key != null && !key.isBlank()) {
172	                return key;
173	            }
174	        }
175	        return null;
176	    }
