178	    /**
179	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
180	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
181	     * identity and per-city gates are applied, the derived registration attributes are
182	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
183	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
184	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
185	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
186	     * of the create pipeline.
187	     */
188	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
189	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
190	        if (!normalizeAndValidateFields(owner)) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
194	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
198	        owner.setRegistrationDate(registrationDate);
199	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	        owner.setHouseholdId(householdId(owner));
203	        owner.setIdentityKey(identityKey(owner));
204	        if (isDuplicate(owner)) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
208	        if (countOwnersInCity(owner.getCity()) >= 50) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        assignRegistrationAttributes(owner, sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
214	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
215	            owner.getMembershipNumber());
216	        HttpHeaders headers = new HttpHeaders();
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
220	    }
