222	    /**
223	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
224	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
225	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
226	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
227	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
228	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
229	     */
230	    private boolean normalizeAndValidateFields(Owner owner) {
231	        if (!normalizeAddressFields(owner)) {
232	            return false;
233	        }
234	        if (owner.getEmail() != null) {
235	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
236	            if (!EMAIL_PATTERN.matcher(email).matches()) {
237	                return false;
238	            }
239	            if (isDisposableEmailDomain(email)) {
240	                return false;
241	            }
242	            owner.setEmail(email);
243	        }
244	        if (!isPostcodeValidForCity(owner)) {
245	            return false;
246	        }
247	        String telephone = normalizeTelephone(owner.getTelephone());
248	        if (telephone == null) {
249	            return false;
250	        }
251	        owner.setTelephone(telephone);
252	        return true;
253	    }
254	
255	    /**
256	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
257	     * returning whether the owner may proceed to creation. The structured fields are preferred when
258	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
259	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
260	     * composed value (the normalized addressLine1, with a single space and the normalized
261	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
262	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
263	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
264	     * address. This is the single place the owner's address is read, canonicalized and written back,
265	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
266	     */
267	    private boolean normalizeAddressFields(Owner owner) {
268	        String line1 = normalizeAddress(owner.getAddressLine1());
269	        if (!line1.isEmpty()) {
270	            String line2 = normalizeAddress(owner.getAddressLine2());
271	            owner.setAddressLine1(line1);
272	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
273	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
274	            return true;
275	        }
276	        String address = normalizeAddress(owner.getAddress());
277	        if (address.isEmpty()) {
278	            return false;
279	        }
280	        owner.setAddress(address);
281	        return true;
282	    }
283	
284	    /**
285	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
286	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
287	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
288	     */
289	    private static boolean isDisposableEmailDomain(String email) {
290	        int at = email.lastIndexOf('@');
291	        if (at < 0) {
292	            return false;
293	        }
294	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
295	    }
