411	    /** Matches a well-formed postcode: exactly 4 digits. */
412	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
413	
414	    /**
415	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
416	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
417	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
418	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
419	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
420	     */
421	    private static boolean isPostcodeValidForCity(Owner owner) {
422	        String postcode = owner.getPostcode();
423	        if (postcode == null) {
424	            return true;
425	        }
426	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
427	            return false;
428	        }
429	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
430	        if (range == null) {
431	            return true;
432	        }
433	        int value = Integer.parseInt(postcode);
434	        return value >= range[0] && value <= range[1];
435	    }
436	
437	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
438	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
439	
440	    /**
441	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
442	     * code are kept when present; otherwise country code '+61' is assumed and a single
443	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
444	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
445	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
446	     * Returns {@code null} when the number cannot form a valid E.164 value.
447	     */
448	    private static String normalizeTelephone(String telephone) {
449	        if (telephone == null) {
450	            return null;
451	        }
452	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
453	        String e164;
454	        if (cleaned.startsWith("+")) {
455	            e164 = cleaned;
456	        } else {
457	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
458	            e164 = "+61" + national;
459	        }
460	        if (!E164_PATTERN.matcher(e164).matches()) {
461	            return null;
462	        }
463	        return hasValidNationalNumberLength(e164) ? e164 : null;
464	    }
465	
466	    /**
467	     * Whether the national number of a well-formed E.164 value has the length required for its
468	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
469	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
470	     */
471	    private static boolean hasValidNationalNumberLength(String e164) {
472	        String countryCode = Owner.countryCodeOf(e164);
473	        if (countryCode == null) {
474	            return true;
475	        }
476	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
477	    }
478	
479	    /**
480	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
481	     * code, membership number, household id, namesake count and household member count. Each is
482	     * derived from the owner's already-normalized fields and the existing owner population, so this
483	     * must run before the owner is saved, while the counts still exclude the owner being created.
484	     *
485	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
486	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
487	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
488	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
489	     */
